// Strip markup to plain prose. The verification step compares the
// model's quotes against THIS string, so whatever normalisation happens here
// must happen there too - hence both sides collapse whitespace and lowercase.
const html = $input.first().json.data ?? $input.first().json.body ?? '';
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ')
  .trim();

if (text.length < 400) {
  throw new Error(`page text is only ${text.length} chars - extraction failed`);
}

return [{ json: { source: text.slice(0, 12000), length: text.length } }];

parameters.text:
Below is the text of one documentation page.

{{ $json.source }}

Write 5 multiple-choice questions that check whether someone can DO the thing
this page teaches — not whether they memorised its wording.

For every question you must supply `justification`, a sentence copied VERBATIM
from the page above that makes the correct answer correct. Copy it exactly,
character for character. If you cannot find such a sentence, do not write the
question.

Return JSON only:
{"questions": [{"question": "...", "options": ["A", "B", "C", "D"], "correct_index": 0, "justification": "..."}]}

