// A question survives only if its justification really is in the page.
// This is the whole point of the workflow: an assessment built on a hallucinated
// justification teaches the wrong thing to everyone who takes it, and it does so
// with a confident answer key.
const source = $('Extract page text').first().json.source;
const raw = $input.first().json.text ?? $input.first().json.output ?? '';

const norm = s => String(s).replace(/\s+/g, ' ').trim().toLowerCase();
const haystack = norm(source);

let parsed;
try {
  parsed = JSON.parse(String(raw).replace(/^```json\s*|\s*```$/g, '').trim());
} catch {
  return [{ json: { kept: [], rejected: [{ reason: 'model output was not JSON' }], any_kept: false } }];
}

const kept = [];
const rejected = [];

for (const q of parsed.questions ?? []) {
  const j = norm(q.justification ?? '');
  if (j.length < 20) {
    rejected.push({ question: q.question, reason: 'justification too short to verify' });
  } else if (!haystack.includes(j)) {
    rejected.push({ question: q.question, reason: 'justification is not in the page' });
  } else {
    kept.push(q);
  }
}

return [{ json: { kept, rejected, any_kept: kept.length > 0 } }];
